check!(request_and_response_objects, "", "const q=new Request('/x', {method:'post', headers:{a:'1'}, body:'b'}); console.log(q.method, q.url, q.headers.get('A'), q.headers.get('content-type')); q.text().then(t=>console.log(t, q.bodyUsed)); const r=new Response('{\"k\":2}', {status:201, statusText:'Made', headers:{'content-type':'application/json'}}); console.log(r.status, r.ok, r.statusText); r.json().then(j=>console.log(j.k)); try { new Response('', {status:99}) } catch(e) { console.log(e.name) }", "POST https://example.test/x 1 text/plain;charset=UTF-8\n201 true Made\nRangeError\nb true\n2");
check!(canvas_default_size_and_state_stack, "<canvas id=c></canvas>", "const x=c.getContext('2d'); console.log(c.width, c.height); x.fillStyle='red'; x.save(); x.fillStyle='blue'; x.globalAlpha=0.5; x.restore(); console.log(x.fillStyle, x.globalAlpha); x.fillStyle='nonsense'; console.log(x.fillStyle); x.lineWidth=-1; x.lineWidth=NaN; console.log(x.lineWidth);", "300 150\n#ff0000 1\n#ff0000\n-1");
