check!(canvas_transform_translate_scale, "<canvas id=c width=10 height=10></canvas>", "const x=c.getContext('2d'); x.translate(2,2); x.scale(2,2); x.fillRect(0,0,2,2); const d=(px,py)=>x.getImageData(px,py,1,1).data[3]; console.log(d(1,1), d(2,2), d(5,5), d(6,6)); x.setTransform(1,0,0,1,0,0); x.clearRect(0,0,10,10); console.log(d(3,3));", "0 255 255 0\n0");
