check!(canvas_global_alpha_blend, "<canvas id=c width=2 height=2></canvas>", "const x=c.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,2,2); x.globalAlpha=0.5; x.fillStyle='#000'; x.fillRect(0,0,2,2); const p=x.getImageData(0,0,1,1).data; console.log(p[0]>120&&p[0]<135, p[3]);", "true 255");
